function shortestSliceToSort(nums: number[]): number {
  const sorted = [...nums].sort((a, b) => a - b);
  let lo = 0, hi = nums.length - 1;
  while (lo < nums.length && nums[lo] === sorted[lo]) lo++;
  if (lo === nums.length) return 0;
  while (nums[hi] === sorted[hi]) hi--;
  return hi - lo + 1;
}

