function shortestSliceToSort(nums: number[]): number {
  const n = nums.length;
  let end = -1, start = 0;
  let maxSeen = -Infinity, minSeen = Infinity;
  for (let i = 0; i < n; i++) {
    if (nums[i] < maxSeen) end = i;
    else maxSeen = nums[i];
  }
  if (end === -1) return 0;
  for (let i = n - 1; i >= 0; i--) {
    if (nums[i] > minSeen) start = i;
    else minSeen = nums[i];
  }
  return end - start + 1;
}

